1	import React, { useState } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { AnimatePresence } from 'framer-motion';
4	import Icon from '../AppIcon';
5	import RestauranteSidebar from './RestauranteSidebar';
6	import MobileMenu from './MobileMenu';
7	import { ThemeToggle } from '../../contexts/ThemeContext';
8	import { useAuth } from '../../contexts/AuthContext';
9	import { useMinhaLojaSlug } from '../../hooks/useMinhaLojaSlug';
10	import { useMinhaLojaLogo } from '../../hooks/useMinhaLojaLogo';
11	import { useModulosEmpresa } from '../../hooks/useModulosEmpresa';
12	import { useSolicitacoesMotoboyCount } from '../../hooks/useSolicitacoesMotoboyCount';
13	import { useRestauranteFavoritos } from '../../hooks/useRestauranteFavoritos';
14	import { getRestauranteNavLinks } from '../../config/restauranteNavLinks';
15	
16	// Header compartilhado de toda a área /restaurante/*. Substitui o header
17	// duplicado (e divergente) que cada página tinha antes — ver plano
18	// "Layout compartilhado + favoritos na topbar".
19	// Bolinha de status do plano na barra superior — verde (em dia), laranja
20	// (vencendo em breve ou vencida mas dentro da tolerância), vermelha (bloqueado).
21	const DIAS_ALERTA_VENCIMENTO = 5;
22	
23	const PlanoStatusDot = ({ planoStatus, onClick }) => {
24	  if (!planoStatus || !planoStatus.plano_nome) return null;
25	
26	  const diasAteVencer = planoStatus.proxima_cobranca
27	    ? Math.ceil((new Date(planoStatus.proxima_cobranca) - new Date()) / 86400000)
28	    : null;
29	
30	  let cor = 'bg-green-500';
31	  let texto = 'Plano em dia';
32	  if (planoStatus.bloqueado) {
33	    cor = 'bg-red-500';
34	    texto = `Painel bloqueado — fatura vencida há ${planoStatus.dias_atraso} dia(s)`;
35	  } else if (planoStatus.dias_atraso > 0) {
36	    cor = 'bg-orange-500';
37	    texto = `Fatura vencida há ${planoStatus.dias_atraso} dia(s) — regularize`;
38	  } else if (diasAteVencer != null && diasAteVencer <= DIAS_ALERTA_VENCIMENTO) {
39	    cor = 'bg-orange-500';
40	    texto = `Próxima cobrança em ${diasAteVencer} dia(s)`;
41	  }
42	
43	  return (
44	    <button onClick={onClick} title={texto}
45	      className="p-2 rounded-lg hover:bg-[#F4F4F5] dark:hover:bg-[#27272A] flex-shrink-0">
46	      <span className={`block w-2.5 h-2.5 rounded-full ${cor} ${planoStatus.bloqueado ? 'animate-pulse' : ''}`} />
47	    </button>
48	  );
49	};
50	
51	const RestauranteHeader = ({ active, title, subtitle }) => {
52	  const navigate = useNavigate();
53	  const { signOut, planoStatus } = useAuth();
54	  const slugLoja = useMinhaLojaSlug();
55	  const logoUrl = useMinhaLojaLogo();
56	  const { moduloDelivery, moduloSalao } = useModulosEmpresa();
57	  const pendentesMotoboy = useSolicitacoesMotoboyCount();
58	  const { favoritos, toggleFavorito, isFavorito } = useRestauranteFavoritos();
59	  const [sidebarAberto, setSidebarAberto] = useState(false);
60	  const [menuAberto, setMenuAberto] = useState(false);
61	
62	  const links = getRestauranteNavLinks(moduloDelivery, moduloSalao);
63	  const linksFavoritos = links.filter((l) => favoritos.includes(l.path));
64	
65	  return (
