1	import React, { useState, useEffect, useRef } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { getPerfil, updatePerfil, uploadFoto } from '../../services/perfilService';
4	import { buscarCep } from '../../utils/viaCep';
5	import { useAuth } from '../../contexts/AuthContext';
6	import Icon from '../../components/AppIcon';
7	
8	const formatCEP = (v) => {
9	  const n = (v ?? '').replace(/\D/g, '');
10	  return n.length <= 8 ? n.replace(/(\d{5})(\d{0,3})/, (_, a, b) => (b ? `${a}-${b}` : a)) : v;
11	};
12	
13	const Campo = ({ label, value, onChange, placeholder, required, type = 'text', readOnly }) => (
14	  <div>
15	    <label className="block text-xs font-medium text-[#71717A] mb-1">{label}{required && <span className="text-red-500 ml-0.5">*</span>}</label>
16	    <input
17	      type={type}
18	      value={value}
19	      onChange={onChange ? (e) => onChange(e.target.value) : undefined}
20	      readOnly={readOnly}
21	      placeholder={placeholder}
22	      className={`w-full border rounded-xl px-3 py-2.5 text-sm focus:outline-none ${
23	        readOnly
24	          ? 'border-[#F4F4F5] bg-[#FAFAFA] text-[#71717A] cursor-default'
25	          : 'border-[#E4E4E7] focus:border-[#FF441F]'
26	      }`}
27	    />
28	  </div>
29	);
30	
31	const CustomerProfile = () => {
32	  const navigate = useNavigate();
33	  const { user, isAuthenticated } = useAuth();
34	
35	  const [form, setForm] = useState({
36	    name: '', phone_e164: '',
37	    logradouro: '', numero: '', complemento: '',
38	    bairro: '', cidade: '', estado: '', cep: '', referencia: '',
39	  });
40	  const [fotoUrl, setFotoUrl] = useState(null);
41	  const [loading, setLoading] = useState(true);
42	  const [salvando, setSalvando] = useState(false);
43	  const [enviandoFoto, setEnviandoFoto] = useState(false);
44	  const [buscandoCep, setBuscandoCep] = useState(false);
45	  const [msg, setMsg] = useState(null);
46	  const fileInputRef = useRef(null);
47	
48	  useEffect(() => {
49	    if (!isAuthenticated()) {
50	      navigate('/customer-registration-login', { state: { from: '/customer-profile' } });
51	      return;
52	    }
53	    getPerfil()
54	      .then((p) => {
55	        const a = p.address_json ?? {};
56	        setForm({
57	          name: p.name ?? '',
58	          phone_e164: p.phone_e164 ?? '',
59	          logradouro: a.logradouro ?? '',
60	          numero: a.numero ?? '',
61	          complemento: a.complemento ?? '',
62	          bairro: a.bairro ?? '',
63	          cidade: a.cidade ?? '',
64	          estado: a.estado ?? '',
65	          cep: a.cep ?? '',
66	          referencia: a.referencia ?? '',
67	        });
68	        setFotoUrl(p.foto_perfil_url ?? null);
69	      })
70	      .catch((e) => setMsg({ tipo: 'erro', texto: e.message }))
71	      .finally(() => setLoading(false));
72	  }, []);
73	
74	  const set = (k) => (v) => setForm((f) => ({ ...f, [k]: v }));
75	
76	  const handleCepChange = async (v) => {
77	    const formatted = formatCEP(v);
78	    setForm((f) => ({ ...f, cep: formatted }));
79	
80	    const digitos = formatted.replace(/\D/g, '');
81	    if (digitos.length !== 8) return;
82	    setBuscandoCep(true);
83	    const endereco = await buscarCep(digitos);
84	    setBuscandoCep(false);
85	    if (!endereco) return;
86	    setForm((f) => ({
87	      ...f,
88	      logradouro: endereco.logradouro || f.logradouro,
89	      bairro: endereco.bairro || f.bairro,
90	      cidade: endereco.cidade || f.cidade,
91	      estado: endereco.estado || f.estado,
92	    }));
93	  };
94	
95	  const handleFotoSelecionada = async (e) => {
96	    const file = e.target.files?.[0];
97	    if (!file) return;
98	    setEnviandoFoto(true);
99	    try {
100	      const { foto_perfil_url } = await uploadFoto(file);
101	      setFotoUrl(foto_perfil_url);
102	    } catch (err) {
103	      setMsg({ tipo: 'erro', texto: err.message });
104	    } finally {
105	      setEnviandoFoto(false);
106	      e.target.value = '';
107	    }
108	  };
109	
110	  const handleSalvar = async (e) => {
111	    e.preventDefault();
112	    if (!form.name.trim() || !form.phone_e164.trim()) {
113	      setMsg({ tipo: 'erro', texto: 'Nome e telefone são obrigatórios.' });
114	      return;
115	    }
116	    if (form.logradouro.trim() && !form.numero.trim()) {
117	      setMsg({ tipo: 'erro', texto: 'Informe o número do endereço.' });
118	      return;
119	    }
120	    setSalvando(true);
121	    setMsg(null);
122	    try {
123	      await updatePerfil({
124	        name: form.name.trim(),
125	        phone_e164: form.phone_e164.trim(),
126	        address_json: {
127	          logradouro: form.logradouro.trim(),
128	          numero: form.numero.trim(),
129	          complemento: form.complemento.trim(),
130	          bairro: form.bairro.trim(),
131	          cidade: form.cidade.trim(),
132	          estado: form.estado.trim(),
133	          cep: form.cep.trim(),
134	          referencia: form.referencia.trim(),
135	        },
136	      });
137	      setMsg({ tipo: 'ok', texto: 'Perfil salvo com sucesso!' });
138	      setTimeout(() => setMsg(null), 3000);
139	    } catch (err) {
140	      setMsg({ tipo: 'erro', texto: err.message });
141	    } finally {
142	      setSalvando(false);
143	    }
144	  };
145	
146	  if (loading) return (
147	    <div className="min-h-screen flex items-center justify-center bg-gray-50">
148	      <div className="w-8 h-8 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
149	    </div>
150	  );
151	
152	  return (
153	    <div className="min-h-screen bg-gray-50 pb-10">
154	      <header className="bg-white border-b px-4 py-4 flex items-center gap-3">
155	        <button onClick={() => navigate(-1)} className="p-2 rounded-xl hover:bg-gray-100">
156	          <Icon name="ArrowLeft" size={20} className="text-gray-600" />
157	        </button>
158	        <div>
159	          <h1 className="text-base font-bold text-[#18181B]">Meu Perfil</h1>
160	          <p className="text-xs text-[#71717A]">Dados e endereço de entrega</p>
161	        </div>
162	      </header>
163	
164	      <main className="max-w-lg mx-auto p-4">
165	        <form onSubmit={handleSalvar} className="space-y-4">
166	          {/* Foto de perfil */}
167	          <div className="bg-white rounded-2xl border border-[#E4E4E7] p-4 flex items-center gap-4">
168	            <button type="button" onClick={() => fileInputRef.current?.click()} disabled={enviandoFoto}
169	              className="relative w-16 h-16 rounded-full overflow-hidden bg-gray-100 flex-shrink-0 border border-[#E4E4E7]">
170	              {fotoUrl
171	                ? <img src={fotoUrl} alt="Foto de perfil" className="w-full h-full object-cover" />
172	                : <div className="w-full h-full flex items-center justify-center"><Icon name="User" size={24} className="text-gray-400" /></div>}
173	              <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity">
174	                <Icon name="Camera" size={16} className="text-white" />
175	              </div>
176	            </button>
177	            <div>
178	              <p className="text-sm font-semibold text-[#18181B]">Foto de perfil</p>
179	              <button type="button" onClick={() => fileInputRef.current?.click()} disabled={enviandoFoto}
180	                className="text-xs text-[#FF441F] font-semibold hover:underline disabled:opacity-50">
181	                {enviandoFoto ? 'Enviando...' : 'Trocar foto'}
182	              </button>
183	            </div>
184	            <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFotoSelecionada} />
185	          </div>
186	
187	          {/* Conta */}
188	          <div className="bg-white rounded-2xl border border-[#E4E4E7] p-4 space-y-3">
189	            <p className="text-sm font-semibold text-[#18181B] flex items-center gap-2">
190	              <Icon name="User" size={14} className="text-[#FF441F]" /> Dados pessoais
191	            </p>
192	            <Campo label="E-mail (não editável)" value={user?.email ?? ''} readOnly />
193	            <Campo label="Nome completo" value={form.name} onChange={set('name')} placeholder="João Silva" required />
194	            <Campo label="WhatsApp / Telefone" value={form.phone_e164} onChange={set('phone_e164')} placeholder="+55 11 99999-9999" required />
195	          </div>
196	
197	          {/* Endereço */}
198	          <div className="bg-white rounded-2xl border border-[#E4E4E7] p-4 space-y-3">
199	            <p className="text-sm font-semibold text-[#18181B] flex items-center gap-2">
200	              <Icon name="MapPin" size={14} className="text-[#FF441F]" /> Endereço de entrega
201	            </p>
202	            <Campo label="Logradouro (Rua / Av.)" value={form.logradouro} onChange={set('logradouro')} placeholder="Rua das Flores" />
203	            <div className="flex gap-2">
204	              <div className="w-1/2">
205	                <Campo label="Número" value={form.numero} onChange={set('numero')} placeholder="123" required={!!form.logradouro.trim()} />
206	              </div>
207	              <div className="w-1/2">
208	                <Campo label="Complemento" value={form.complemento} onChange={set('complemento')} placeholder="Apto 4" />
209	              </div>
210	            </div>
211	            <Campo label="Bairro" value={form.bairro} onChange={set('bairro')} placeholder="Centro" />
212	            <div className="flex gap-2">
213	              <div className="flex-1">
214	                <Campo label="Cidade" value={form.cidade} onChange={set('cidade')} placeholder="São Paulo" />
215	              </div>
216	              <div className="w-20">
217	                <Campo label="UF" value={form.estado} onChange={set('estado')} placeholder="SP" />
218	              </div>
219	            </div>
220	            <Campo label="CEP" value={form.cep} onChange={handleCepChange} placeholder="00000-000" />
221	            {buscandoCep && <p className="text-[11px] text-[#71717A] -mt-2">Buscando endereço...</p>}
222	            <Campo label="Ponto de referência" value={form.referencia} onChange={set('referencia')} placeholder="Próximo ao mercado..." />
223	          </div>
224	
225	          {msg && (
226	            <div className={`text-sm rounded-xl px-4 py-3 ${
