232	
233	          <button type="submit" disabled={salvando}
234	            className="w-full py-3.5 bg-[#FF441F] text-white font-bold rounded-2xl hover:bg-[#E63A19] disabled:opacity-50 shadow-lg shadow-[#FF441F]/20 text-sm">
235	            {salvando ? 'Salvando...' : 'Salvar perfil'}
236	          </button>
237	        </form>
238	      </main>
239	    </div>
