1	import { Body, Controller, Post, Req, UseGuards } from '@nestjs/common';
2	import { JwtGuard } from '../auth/jwt.guard';
3	import { SupabaseService } from '../supabase/supabase.service';
4	import { GeocodingService } from '../motoboy/geocoding.service';
5	
6	@Controller('restaurante')
7	export class OnboardingController {
8	  constructor(
9	    private supabase: SupabaseService,
10	    private geocoding: GeocodingService,
11	  ) {}
12	
13	  // Endpoint acessível por qualquer usuário logado — cria restaurante e eleva role
14	  @Post('registrar')
15	  @UseGuards(JwtGuard)
16	  async registrar(
17	    @Req() req: any,
18	    @Body()
19	    body: {
20	      name: string;
21	      address?: string;
22	      state?: string;
23	      city?: string;
24	      neighborhood?: string;
25	      cep?: string;
26	      business_hours?: object;
27	      type_id?: number;
28	    },
29	  ) {
30	    const userId: string = req.userId;
31	
32	    // Se já tem restaurante, retorna ele
33	    const { data: existing } = await this.supabase.client
34	      .from('restaurants')
35	      .select('id, name')
36	      .eq('user_id', userId)
37	      .maybeSingle();
38	
39	    if (existing) return { restaurant: existing, already_registered: true };
40	
41	    const slug = body.name.toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').trim();
42	
43	    // Cria restaurante
44	    const { data: restaurant, error } = await this.supabase.client
45	      .from('restaurants')
46	      .insert({
47	        name: body.name,
48	        address: body.address ?? null,
49	        state: body.state ?? null,
50	        city: body.city ?? null,
51	        neighborhood: body.neighborhood ?? null,
52	        cep: body.cep ? body.cep.replace(/\D/g, '') : null,
53	        business_hours: body.business_hours ?? {},
54	        type_id: body.type_id ?? null,
55	        user_id: userId,
56	        // comissao_pct fica NULL — usa o padrão global da plataforma até o admin definir um override
57	        slug,
58	      })
59	      .select()
60	      .single();
61	
62	    if (error) throw error;
63	
64	    // Geocodifica em background (best-effort) — sem isso o restaurante nunca aparece no
65	    // filtro por raio/km da home até o dono re-salvar o endereço em Config manualmente.
66	    if (restaurant.address || restaurant.cep) {
