107:            {iconName && iconPosition === 'right' && renderIcon()}
125:                    {loading && <LoadingSpinner />}
126:                    {iconName && iconPosition === 'left' && renderIcon()}
128:                    {iconName && iconPosition === 'right' && renderIcon()}
135:                    fullWidth && "w-full",
138:                disabled: disabled || loading || child?.props?.disabled,
152:                fullWidth && "w-full"
155:            disabled={disabled || loading}

