1	import { BadRequestException, Body, Controller, Get, Post, Req, UseGuards } from '@nestjs/common';
2	import { JwtGuard } from '../auth/jwt.guard';
3	import { RestaurantOwnerGuard } from '../auth/restaurant-owner.guard';
4	import { SupabaseService } from '../supabase/supabase.service';
5	import { GeocodingService } from '../motoboy/geocoding.service';
6	import { PlanosService } from '../planos/planos.service';
7	
8	@Controller('restaurante')
9	export class OnboardingController {
10	  constructor(
11	    private supabase: SupabaseService,
12	    private geocoding: GeocodingService,
13	    private planos: PlanosService,
14	  ) {}
15	
16	  // Público (sem guard) — a wizard de cadastro mostra os planos antes do
17	  // usuário logar/criar conta, pra ele escolher já na primeira etapa.
18	  @Get('planos-disponiveis')
19	  planosDisponiveis() {
20	    return this.planos.listarPlanosAtivos('saas');
21	  }
22	
23	  // 1ª fase do cadastro: cria a loja só com nome + assinatura do plano
24	  // escolhido, e cobra a fatura do período atual na hora se o plano não tiver
25	  // trial. O resto do formulário (endereço, horários, tipo...) só é liberado
26	  // na wizard depois que essa fatura confirmar paga (ou, se for plano com
27	  // trial, direto). Idempotente: se o usuário já tem restaurante (reload no
28	  // meio do checkout), retorna o estado atual em vez de criar de novo.
29	  @Post('registrar-inicial')
30	  @UseGuards(JwtGuard)
31	  async registrarInicial(@Req() req: any, @Body() body: { name?: string; plano_id?: number }) {
32	    const userId: string = req.userId;
33	
34	    const { data: existing } = await this.supabase.client
35	      .from('restaurants')
36	      .select('id, name')
37	      .eq('user_id', userId)
38	      .maybeSingle();
