async getConfig() {
  const { data } = await this.supabase.client
    .from('platform_settings')
    .select('config')
    .eq('id', 1)
    .maybeSingle();

  const cfg = (data?.config ?? {}) as Record<string, any>;

  return {
    pagbank_platform_account_id: cfg.pagbank_platform_account_id ?? '',
    pagbank_sandbox: cfg.pagbank_sandbox ?? true,
    pagbank_platform_token_masked: cfg.pagbank_platform_token
      ? `${'•'.repeat(8)}${String(cfg.pagbank_platform_token).slice(-4)}`
      : null,
    configurado: !!(cfg.pagbank_platform_token && cfg.pagbank_platform_account_id),
    // Instalação individual (mono-estabelecimento)
    modo_individual: cfg.modo_individual ?? false,
    modo_individual_restaurant_id: cfg.modo_individual_restaurant_id ?? null,
    // Comissão padrão e tolerância de inadimplência de planos
    comissao_padrao_pct: cfg.comissao_padrao_pct ?? 5,
    plano_dias_tolerancia: cfg.plano_dias_tolerancia ?? 3,
  };
}

async updateConfig(body: {
  pagbank_platform_token?: string;
  pagbank_platform_account_id?: string;
  pagbank_sandbox?: boolean;
  modo_individual?: boolean;
  modo_individual_restaurant_id?: number | null;
  comissao_padrao_pct?: number;
  plano_dias_tolerancia?: number;
}) {
  const { data: atual } = await this.supabase.client
    .from('platform_settings')
    .select('config')
    .eq('id', 1)
    .maybeSingle();

  const cfg = (atual?.config ?? {}) as Record<string, any>;
  const novo: Record<string, any> = { ...cfg };

  if (body.pagbank_platform_token?.trim()) {
    novo.pagbank_platform_token = body.pagbank_platform_token.trim();
  }
  if (body.pagbank_platform_account_id !== undefined) {
    novo.pagbank_platform_account_id = body.pagbank_platform_account_id;
  }
  if (body.pagbank_sandbox !== undefined) {
    novo.pagbank_sandbox = body.pagbank_sandbox;
  }
  if (body.modo_individual !== undefined) {
    novo.modo_individual = body.modo_individual;
  }
  if (body.modo_individual_restaurant_id !== undefined) {
    novo.modo_individual_restaurant_id = body.modo_individual_restaurant_id;
  }
  if (body.comissao_padrao_pct !== undefined) {
    novo.comissao_padrao_pct = body.comissao_padrao_pct;
  }
  if (body.plano_dias_tolerancia !== undefined) {
    novo.plano_dias_tolerancia = body.plano_dias_tolerancia;
  }

  const { error } = await this.supabase.client
    .from('platform_settings')
    .update({ config: novo, updated_at: new Date().toISOString() })
    .eq('id', 1);

  if (error) throw error;
  return this.getConfig();
}

